<?php
use App\Http\Controllers\Api\{AuthController,DashboardController,OrderController};use Illuminate\Support\Facades\Route;
Route::middleware(['throttle:login','device.context'])->post('/login',[AuthController::class,'login']);
Route::middleware(['auth:sanctum','device.context'])->group(function(){Route::post('/logout',[AuthController::class,'logout']);Route::get('/me',[AuthController::class,'me']);Route::get('/dashboard',DashboardController::class);Route::get('/orders',[OrderController::class,'index']);Route::get('/orders/{order}',[OrderController::class,'show']);Route::post('/orders/{order}/start-delivery',[OrderController::class,'start']);Route::post('/orders/{order}/verify-delivery-code',[OrderController::class,'verify'])->middleware('throttle:delivery-code');Route::post('/orders/{order}/payment',[OrderController::class,'payment']);Route::post('/orders/{order}/complete-delivery',[OrderController::class,'complete']);Route::post('/orders/{order}/delivery-failed',[OrderController::class,'failed']);});
